t.script:
setTimeout(function(){
    var t = document.querySelector('.toast.show');
    if(t) t.classList.remove('show');
    if (window.history.replaceState) {
        var url = new URL(window.location.href);
        url.searchParams.delete('error');
        window.history.replaceState({path: url.href}, '', url.href);
    }
}, 5000);

function switchLeaveScopeTab(scope) {
    var myWrap = document.getElementById('leave-history-my');
    var allWrap = document.getElementById('leave-history-all');
    var tabMy = document.getElementById('tab-leave-my');
    var tabAll = document.getElementById('tab-leave-all');

    if (scope === 'my') {
        if(myWrap) myWrap.style.display = 'block';
        if(allWrap) allWrap.style.display = 'none';
        if(tabMy) {
            tabMy.style.borderBottom = '3px solid #4c1d95';
            tabMy.style.opacity = '1';
            tabMy.classList.add('active');
        }
        if(tabAll) {
            tabAll.style.borderBottom = '3px solid transparent';
            tabAll.style.opacity = '0.6';
            tabAll.classList.remove('active');
        }
    } else {
        if(myWrap) myWrap.style.display = 'none';
        if(allWrap) allWrap.style.display = 'block';
        if(tabMy) {
            tabMy.style.borderBottom = '3px solid transparent';
            tabMy.style.opacity = '0.6';
            tabMy.classList.remove('active');
        }
        if(tabAll) {
            tabAll.style.borderBottom = '3px solid #4c1d95';
            tabAll.style.opacity = '1';
            tabAll.classList.add('active');
        }
    }
}

div.script:
function triggerEditLeaveFromTable(btn) {
    var leaveId = btn.getAttribute('data-leave-id');
    var holidayStatusId = btn.getAttribute('data-holiday-status-id');
    var dateFrom = btn.getAttribute('data-date-from');
    var dateTo = btn.getAttribute('data-date-to');
    var reason = btn.getAttribute('data-reason');
    var isHalf = btn.getAttribute('data-half-day') === 'true';
    var period = btn.getAttribute('data-period');

    var form = document.getElementById('editLeaveForm');
    if (form) {
        form.action = '/my/leaves/update/' + leaveId;
        var typeSelect = document.getElementById('edit_holiday_status_id');
        if (typeSelect) typeSelect.value = holidayStatusId;
        var dtFrom = document.getElementById('edit_leave_date_from');
        if (dtFrom) dtFrom.value = dateFrom;
        var dtTo = document.getElementById('edit_leave_date_to');
        if (dtTo) dtTo.value = dateTo;
        var reasonInput = document.getElementById('edit_leave_name');
        if (reasonInput) reasonInput.value = reason || '';

        var halfCheck = document.getElementById('edit_is_half_day');
        var periodWrap = document.getElementById('edit_half_day_period_container');
        var dateToWrap = document.getElementById('edit_leave_date_to_container');
        if (halfCheck) {
            halfCheck.checked = isHalf;
            if (isHalf) {
                if (periodWrap) periodWrap.style.display = 'block';
                if (dateToWrap) dateToWrap.style.display = 'none';
                var periodSel = document.getElementById('edit_request_date_from_period');
                if (periodSel) periodSel.value = period || 'am';
            } else {
                if (periodWrap) periodWrap.style.display = 'none';
                if (dateToWrap) dateToWrap.style.display = 'block';
            }
        }

        var cancelBtn = document.getElementById('edit_cancel_leave_btn');
        if (cancelBtn) {
            cancelBtn.href = '/my/leaves/cancel/' + leaveId;
        }

        if (typeof checkTeamCollision === 'function') {
            checkTeamCollision('edit_leave_date_from', 'edit_leave_date_to', 'edit_is_half_day', 'edit_team_collision_warning', 'edit_collision_dept_name', 'edit_collision_list', leaveId);
        }

        $('#editLeaveModal').modal('show');
    }
}

function handleEditLeaveFilesSelect(input) {
    var filesList = document.getElementById('edit_leave_files_list');
    var prompt = document.getElementById('edit_dropzone_prompt');
    if (!input.files || input.files.length === 0) {
        if (filesList) { filesList.classList.add('d-none'); filesList.innerHTML = ''; }
        if (prompt) prompt.style.display = 'block';
        return;
    }
    if (prompt) prompt.style.display = 'none';
    if (filesList) {
        filesList.classList.remove('d-none');
        filesList.innerHTML = '';
        for (var i = 0; i < input.files.length; i++) {
            var file = input.files[i];
            var sizeKb = (file.size / 1024).toFixed(1);
            var sizeStr = sizeKb > 1024 ? (sizeKb / 1024).toFixed(1) + ' MB' : sizeKb + ' KB';
            var fileCard = document.createElement('div');
            fileCard.className = 'd-flex align-items-center justify-content-between p-2 mb-2 bg-white rounded shadow-sm border';
            fileCard.innerHTML = '<div class="d-flex align-items-center"><span class="me-2 text-primary" style="font-size: 1.2rem;"><i class="fa fa-file-text-o"/></span><div><div class="font-weight-bold text-dark small" style="word-break: break-all;">' + file.name + '</div><div class="text-muted" style="font-size: 0.75rem;">' + sizeStr + '</div></div></div><span class="badge bg-success text-white rounded-circle p-1" style="font-size: 0.75rem;"><i class="fa fa-check"/></span>';
            filesList.appendChild(fileCard);
        }
    }
}
function handleLeaveFilesSelect(input) {
    var filesList = document.getElementById('leave_files_list');
    var prompt = document.getElementById('dropzone_prompt');
    if (!input.files || input.files.length === 0) {
        if (filesList) { filesList.classList.add('d-none'); filesList.innerHTML = ''; }
        if (prompt) prompt.style.display = 'block';
        return;
    }

    if (prompt) prompt.style.display = 'none';
    if (filesList) {
        filesList.classList.remove('d-none');
        filesList.innerHTML = '';

        for (var i = 0; i < input.files.length; i++) {
            var file = input.files[i];
            var sizeKb = (file.size / 1024).toFixed(1);
            var sizeStr = sizeKb > 1024 ? (sizeKb / 1024).toFixed(1) + ' MB' : sizeKb + ' KB';

            var fileCard = document.createElement('div');
            fileCard.className = 'd-flex align-items-center justify-content-between p-2 mb-2 bg-white rounded shadow-sm border';
            fileCard.innerHTML = '<div class="d-flex align-items-center">' +
                '<span class="me-2 text-primary" style="font-size: 1.2rem;"><i class="fa fa-file-text-o"/></span>' +
                '<div>' +
                    '<div class="font-weight-bold text-dark small" style="word-break: break-all;">' + file.name + '</div>' +
                    '<div class="text-muted" style="font-size: 0.75rem;">' + sizeStr + '</div>' +
                '</div>' +
            '</div>' +
            '<span class="badge bg-success text-white rounded-circle p-1" style="font-size: 0.75rem;"><i class="fa fa-check"/></span>';

            filesList.appendChild(fileCard);
        }
    }
}

function handleLeaveDrop(e) {
    var dt = e.dataTransfer;
    var files = dt.files;
    var fileInput = document.getElementById('leave_attachment');
    if (files && files.length > 0 && fileInput) {
        fileInput.files = files;
        handleLeaveFilesSelect(fileInput);
    }
}

function checkMandatoryAttachmentOnSubmit(formEl, selectId, dateFromId, dateToId, isHalfDayId, fileInputName, isEdit) {
    var sel = document.getElementById(selectId);
    if (!sel || !sel.options[sel.selectedIndex]) return true;
    var opt = sel.options[sel.selectedIndex];
    var isMandatory = opt.getAttribute('data-mandatory-att') === 'true';
    var minDays = parseFloat(opt.getAttribute('data-min-days') || '2.0');

    if (isMandatory) {
        var isHalf = isHalfDayId ? (document.getElementById(isHalfDayId) && document.getElementById(isHalfDayId).checked) : false;
        var dFrom = document.getElementById(dateFromId) ? document.getElementById(dateFromId).value : '';
        var dTo = document.getElementById(dateToId) ? document.getElementById(dateToId).value : dFrom;

        var totalDays = 1.0;
        if (isHalf) {
            totalDays = 0.5;
        } else if (dFrom && dTo) {
            var dt1 = new Date(dFrom);
            var dt2 = new Date(dTo);
            totalDays = Math.round((dt2 - dt1) / (1000 * 60 * 60 * 24)) + 1;
        }

        if (totalDays > minDays) {
            var fileInput = formEl.querySelector('input[type="file"][name="' + fileInputName + '"]');
            var hasNewFile = fileInput && fileInput.files && fileInput.files.length > 0;
            if (isEdit) {
                var attsList = document.getElementById('edit_existing_attachments_list');
                var hasExisting = attsList && attsList.children && attsList.children.length > 0;
                if (!hasNewFile && !hasExisting) {
                    alert("Attachment is mandatory for '" + opt.text.trim() + "' when duration (" + totalDays + " days) exceeds " + minDays + " days.");
                    return false;
                }
            } else {
                if (!hasNewFile) {
                    alert("Attachment is mandatory for '" + opt.text.trim() + "' when duration (" + totalDays + " days) exceeds " + minDays + " days.");
                    return false;
                }
            }
        }
    }
    return true;
}

function checkTeamCollision(dateFromId, dateToId, isHalfDayId, warningWrapId, deptNameId, listId, leaveId) {
    var dFromEl = document.getElementById(dateFromId);
    var dToEl = document.getElementById(dateToId);
    var isHalfEl = isHalfDayId ? document.getElementById(isHalfDayId) : null;

    var dFrom = dFromEl ? dFromEl.value : '';
    var isHalf = isHalfEl ? isHalfEl.checked : false;
    var dTo = isHalf ? dFrom : (dToEl ? dToEl.value : dFrom);

    var wrap = document.getElementById(warningWrapId);
    var deptEl = document.getElementById(deptNameId);
    var listEl = document.getElementById(listId);

    if (!dFrom || !wrap || !listEl) return;

    fetch('/my/leaves/check_collision', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            jsonrpc: '2.0',
            method: 'call',
            params: {
                date_from: dFrom,
                date_to: dTo,
                leave_id: leaveId || null
            }
        })
    }).then(function(res) { return res.json(); })
      .then(function(data) {
          if (data && data.result && data.result.collisions && data.result.collisions.length > 0) {
              if (deptEl) deptEl.textContent = data.result.department_name || 'your team';
              listEl.innerHTML = '';
              data.result.collisions.forEach(function(c) {
                  var li = document.createElement('li');
                  li.innerHTML = '<strong>' + c.employee_name + '</strong> (' + c.leave_type + ') — <span class="text-secondary">' + c.date_range + '</span>';
                  listEl.appendChild(li);
              });
              wrap.classList.remove('d-none');
          } else {
              wrap.classList.add('d-none');
              listEl.innerHTML = '';
          }
      }).catch(function(err) {
          console.error("Collision check error:", err);
      });
}

document.addEventListener('DOMContentLoaded', function() {
    ['leave_date_from', 'leave_date_to', 'is_half_day'].forEach(function(id) {
        var el = document.getElementById(id);
        if (el) {
            el.addEventListener('change', function() {
                checkTeamCollision('leave_date_from', 'leave_date_to', 'is_half_day', 'new_team_collision_warning', 'new_collision_dept_name', 'new_collision_list', null);
            });
        }
    });

    ['edit_leave_date_from', 'edit_leave_date_to', 'edit_is_half_day'].forEach(function(id) {
        var el = document.getElementById(id);
        if (el) {
            el.addEventListener('change', function() {
                var form = document.getElementById('editLeaveForm');
                var leaveId = form && form.action ? form.action.split('/').pop() : null;
                checkTeamCollision('edit_leave_date_from', 'edit_leave_date_to', 'edit_is_half_day', 'edit_team_collision_warning', 'edit_collision_dept_name', 'edit_collision_list', leaveId);
            });
        }
    });
    const form = document.querySelector('#newLeaveModal form');
    if(form) {
        form.addEventListener('submit', function(e) {
            if (!checkMandatoryAttachmentOnSubmit(this, 'holiday_status_id', 'leave_date_from', 'leave_date_to', 'is_half_day', 'attachment', false)) {
                e.preventDefault();
                e.stopImmediatePropagation();
                return false;
            }
            e.preventDefault();
            const formData = new FormData(form);
            fetch(form.action, {
                method: 'POST',
                body: formData,
            })
            .then(response => {
                if (response.redirected) {
                    var url = new URL(response.url);
                    if (url.searchParams.has('error')) {
                        var errorMsg = url.searchParams.get('error');
                        var toastContainer = document.getElementById('dynamic-toast-container');
                        if (!toastContainer) {
                            toastContainer = document.createElement('div');
                            toastContainer.id = 'dynamic-toast-container';
                            toastContainer.className = 'position-fixed';
                            toastContainer.style.zIndex = '1055';
                            toastContainer.style.right = '20px';
                            toastContainer.style.top = '80px';
                            document.body.appendChild(toastContainer);
                        }
                        var toastHTML = `






                                         ${errorMsg}


                                        &times;



                        `;
                        toastContainer.insertAdjacentHTML('beforeend', toastHTML);
                        setTimeout(function() {
                            if (toastContainer.lastElementChild) toastContainer.lastElementChild.remove();
                        }, 5000);
                    } else {
                        window.location.href = response.url;
                    }
                } else {
                    window.location.href = '/my/leaves';
                }
            })
            .catch(error => {
                console.error('Error submitting form:', error);
            });
        });
    }
});

document.addEventListener('DOMContentLoaded', function() {
    var calendarEl = document.getElementById('leave_calendar');
    if (calendarEl) {
        var calendar = new FullCalendar.Calendar(calendarEl, {
            initialView: 'dayGridMonth',
            headerToolbar: {
                left: 'prev,next today',
                center: 'title',
                right: 'dayGridMonth,timeGridWeek'
            },
            events: function(info, successCallback, failureCallback) {
                fetch('/my/leaves/get_events', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                    body: JSON.stringify({
                        jsonrpc: '2.0',
                        method: 'call',
                        params: {
                            start: info.startStr,
                            end: info.endStr
                        }
                    })
                }).then(response => response.json())
                  .then(data => {
                      if (data.result) {
                          successCallback(data.result);
                      } else {
                          successCallback([]);
                      }
                  }).catch(error => {
                      console.error("Error fetching events:", error);
                      failureCallback(error);
                  });
            },
            dateClick: function(info) {
                // Open the apply leave modal and pre-fill the clicked date
                var dateInputFrom = document.getElementById('leave_date_from');
                var dateInputTo = document.getElementById('leave_date_to');
                if (dateInputFrom) {
                    dateInputFrom.value = info.dateStr;
                }
                if (dateInputTo) {
                    dateInputTo.value = info.dateStr;
                }
                if (typeof checkTeamCollision === 'function') {
                    checkTeamCollision('leave_date_from', 'leave_date_to', 'is_half_day', 'new_team_collision_warning', 'new_collision_dept_name', 'new_collision_list', null);
                }
                $('#newLeaveModal').modal('show');
            },
            eventClick: function(info) {
                var props = info.event.extendedProps;
                if (props && props.leave_id) {
                    if (props.is_owner && (props.state === 'draft' || props.state === 'confirm' || props.state === 'validate1')) {
                        var form = document.getElementById('editLeaveForm');
                        if (form) {
                            form.action = '/my/leaves/update/' + props.leave_id;
                            var typeSelect = document.getElementById('edit_holiday_status_id');
                            if (typeSelect) typeSelect.value = props.holiday_status_id;
                            var dtFrom = document.getElementById('edit_leave_date_from');
                            if (dtFrom) dtFrom.value = props.date_from_val;
                            var dtTo = document.getElementById('edit_leave_date_to');
                            if (dtTo) dtTo.value = props.date_to_val;
                            var reasonInput = document.getElementById('edit_leave_name');
                            if (reasonInput) reasonInput.value = props.reason || '';

                            var halfCheck = document.getElementById('edit_is_half_day');
                            var periodWrap = document.getElementById('edit_half_day_period_container');
                            var dateToWrap = document.getElementById('edit_leave_date_to_container');
                            if (halfCheck) {
                                halfCheck.checked = props.request_unit_half;
                                if (props.request_unit_half) {
                                    if (periodWrap) periodWrap.style.display = 'block';
                                    if (dateToWrap) dateToWrap.style.display = 'none';
                                    var periodSel = document.getElementById('edit_request_date_from_period');
                                    if (periodSel) periodSel.value = props.request_date_from_period || 'am';
                                } else {
                                    if (periodWrap) periodWrap.style.display = 'none';
                                    if (dateToWrap) dateToWrap.style.display = 'block';
                                }
                            }

                            var attsWrap = document.getElementById('edit_existing_attachments_wrapper');
                            var attsList = document.getElementById('edit_existing_attachments_list');
                            if (attsWrap && attsList) {
                                if (props.attachments && props.attachments.length > 0) {
                                    attsWrap.classList.remove('d-none');
                                    attsList.innerHTML = '';
                                    props.attachments.forEach(function(att) {
                                        var a = document.createElement('a');
                                        a.href = '/my/leaves/attachment/' + att.id;
                                        a.target = '_blank';
                                        a.className = 'btn btn-sm btn-outline-primary me-1 mb-1';
                                        a.style.borderRadius = '6px';
                                        a.innerHTML = ' ' + att.name;
                                        attsList.appendChild(a);
                                    });
                                } else {
                                    attsWrap.classList.add('d-none');
                                    attsList.innerHTML = '';
                                }
                            }

                            var cancelBtn = document.getElementById('edit_cancel_leave_btn');
                            if (cancelBtn) {
                                cancelBtn.href = '/my/leaves/cancel/' + props.leave_id;
                            }

                            $('#editLeaveModal').modal('show');
                        }
                    } else {
                        var typeTitle = document.getElementById('view_leave_type_name');
                        if (typeTitle) typeTitle.innerText = props.holiday_status_name || info.event.title;
                        var badge = document.getElementById('view_leave_status_badge');
                        if (badge) {
                            if (props.cancellation_requested) {
                                badge.innerText = 'APPROVED (CANCELLATION REQUESTED)';
                                badge.className = 'badge bg-warning text-dark';
                            } else {
                                var st = props.state ? props.state.toUpperCase() : 'APPROVED';
                                badge.innerText = st;
                                badge.className = (props.state === 'validate') ? 'badge bg-success text-white' : (props.state === 'refuse' ? 'badge bg-danger text-white' : 'badge bg-warning text-white');
                            }
                        }
                        var dtLabel = document.getElementById('view_leave_dates');
                        if (dtLabel) dtLabel.innerText = (props.date_from_val || '') + ' to ' + (props.date_to_val || '');
                        var reasonDiv = document.getElementById('view_leave_reason');
                        if (reasonDiv) reasonDiv.innerText = props.reason || 'No description provided.';

                        var attsWrap = document.getElementById('view_existing_attachments_wrapper');
                        var attsList = document.getElementById('view_existing_attachments_list');
                        if (attsWrap && attsList) {
                            if (props.attachments && props.attachments.length > 0) {
                                attsWrap.classList.remove('d-none');
                                attsList.innerHTML = '';
                                props.attachments.forEach(function(att) {
                                    var a = document.createElement('a');
                                    a.href = '/my/leaves/attachment/' + att.id;
                                    a.target = '_blank';
                                    a.className = 'btn btn-sm btn-outline-primary me-1 mb-1';
                                    a.style.borderRadius = '6px';
                                    a.innerHTML = ' ' + att.name;
                                    attsList.appendChild(a);
                                });
                            } else {
                                attsWrap.classList.add('d-none');
                                attsList.innerHTML = '';
                            }
                        }

                        var cancelReasonWrap = document.getElementById('view_cancellation_reason_wrapper');
                        var cancelReasonDiv = document.getElementById('view_cancellation_reason');
                        if (cancelReasonWrap && cancelReasonDiv) {
                            if (props.cancellation_requested && props.cancellation_reason) {
                                cancelReasonDiv.innerText = props.cancellation_reason;
                                cancelReasonWrap.classList.remove('d-none');
                            } else {
                                cancelReasonWrap.classList.add('d-none');
                            }
                        }

                        var viewCancelBtn = document.getElementById('view_cancel_leave_btn');
                        if (viewCancelBtn) {
                            var isManager = ;
                            if (props.leave_id && props.state !== 'refuse' && (props.is_owner || isManager)) {
                                if (props.cancellation_requested) {
                                    viewCancelBtn.href = 'javascript:void(0);';
                                    viewCancelBtn.innerHTML = ' Cancellation Pending Approval';
                                    viewCancelBtn.className = 'btn btn-outline-secondary disabled';
                                    viewCancelBtn.removeAttribute('onclick');
                                } else if (props.state === 'validate') {
                                    viewCancelBtn.href = 'javascript:void(0);';
                                    viewCancelBtn.innerHTML = ' Request Cancellation';
                                    viewCancelBtn.className = 'btn btn-outline-warning';
                                    viewCancelBtn.setAttribute('onclick', "var r=prompt('Please provide a reason for requesting cancellation of this approved leave:'); if(r!==null){ window.location.href='/my/leaves/cancel/" + props.leave_id + "?reason=' + encodeURIComponent(r); } return false;");
                                } else {
                                    viewCancelBtn.href = '/my/leaves/cancel/' + props.leave_id;
                                    viewCancelBtn.innerHTML = ' Cancel Leave';
                                    viewCancelBtn.className = 'btn btn-outline-danger';
                                    viewCancelBtn.setAttribute('onclick', "return confirm('Are you sure you want to cancel this leave request?');");
                                }
                                viewCancelBtn.classList.remove('d-none');
                            } else {
                                viewCancelBtn.classList.add('d-none');
                            }
                        }

                        $('#viewLeaveModal').modal('show');
                    }
                }
            }
        });
        calendar.render();
    }

    // Leave Type Change Logic
    var leaveTypeSelect = document.getElementById('holiday_status_id');
    var fullDayOptions = document.getElementById('full_day_options');
    var partialDayOptions = document.getElementById('partial_day_options');
    var dateToContainer = document.getElementById('leave_date_to_container');
    var dateToInput = document.getElementById('leave_date_to');
    var partialMinutesInput = document.querySelector('input[name="partial_minutes"]');

    if (leaveTypeSelect) {
        leaveTypeSelect.addEventListener('change', function() {
            var selectedOption = this.options[this.selectedIndex];
            var reqUnit = selectedOption.getAttribute('data-request-unit');
            if (reqUnit === 'hour') {
                fullDayOptions.style.display = 'none';
                partialDayOptions.style.display = 'block';
                dateToContainer.style.display = 'none';
                dateToInput.removeAttribute('required');
                partialMinutesInput.setAttribute('required', '1');
            } else {
                fullDayOptions.style.display = 'block';
                partialDayOptions.style.display = 'none';
                dateToContainer.style.display = 'block';
                dateToInput.setAttribute('required', '1');
                partialMinutesInput.removeAttribute('required');
            }
            // Reset half day on change
            var halfDayCheckbox = document.getElementById('is_half_day');
            if(halfDayCheckbox && halfDayCheckbox.checked) {
                halfDayCheckbox.checked = false;
                halfDayCheckbox.dispatchEvent(new Event('change'));
            }
        });
    }

    // Partial Type Radio Logic
    var radios = document.querySelectorAll('input[name="partial_type"]');
    var prefixSpan = document.getElementById('partial_text_prefix');
    if (radios.length > 0) {
        radios.forEach(function(radio) {
            radio.addEventListener('change', function() {
                if (this.value === 'late') {
                    prefixSpan.textContent = 'Will come late by';
                } else {
                    prefixSpan.textContent = 'Will leave early by';
                }
            });
        });
    }

    // Half Day Toggle Logic
    var halfDayCheckbox = document.getElementById('is_half_day');
    var dateToContainer = document.getElementById('leave_date_to_container');
    var dateToInput = document.getElementById('leave_date_to');
    var periodContainer = document.getElementById('half_day_period_container');
    var periodInput = document.getElementById('request_date_from_period');

    if (halfDayCheckbox) {
        halfDayCheckbox.addEventListener('change', function() {
            if (this.checked) {
                dateToContainer.style.display = 'none';
                dateToInput.removeAttribute('required');
                periodContainer.style.display = 'block';
                periodInput.setAttribute('required', '1');
            } else {
                dateToContainer.style.display = 'block';
                dateToInput.setAttribute('required', '1');
                periodContainer.style.display = 'none';
                periodInput.removeAttribute('required');
            }
        });
    }
    var editForm = document.getElementById('editLeaveForm');
    if (editForm) {
        editForm.addEventListener('submit', function(e) {
            if (!checkMandatoryAttachmentOnSubmit(this, 'edit_holiday_status_id', 'edit_leave_date_from', 'edit_leave_date_to', 'edit_is_half_day', 'attachment', true)) {
                e.preventDefault();
                e.stopPropagation();
                return false;
            }
        });
    }
});
